#!/usr/bin/env bash
# Collect Rust coverage from the SDKs' existing no-VM native boundary tests.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$root"
# SDK builds change directories; share one absolute object directory.
CARGO_TARGET_DIR="${CARGO_TARGET_DIR:-$root/target/native-sdk-coverage}"
case "$CARGO_TARGET_DIR" in
    /*) ;;
    *) CARGO_TARGET_DIR="$root/$CARGO_TARGET_DIR" ;;
esac
export CARGO_TARGET_DIR
export SETUP_DONE=1

# show-env instruments Cargo builds invoked by maturin, napi and make too.
# Its output is generated by the installed collector, not repository input.
eval "$(cargo llvm-cov show-env --sh)"
cargo llvm-cov clean --workspace

make dev:python dev:node
make test:unit:c
make coverage:python
# These suites use loopback HTTP and an empty local cache; they never boot a VM.
make test:integration:node FILTER='image catalog|registry logins'

mkdir -p "$root/target/coverage/native-sdk"
# napi builds under the explicit host triple; also scan it alongside debug/.
host="$(rustc -vV | sed -n 's/^host: //p')"
cargo llvm-cov report --lcov --target "$host" \
    --ignore-filename-regex '(^|/)(src/deps/[^/]+/vendor|src/test-utils|tests)/' \
    --output-path "$root/target/coverage/native-sdk/lcov.info"
